import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;

/** Pictures taken from the UI design, embedded in the code so no image files are needed. */
public final class Images {
    private Images() { }

    private static final Map<String, BufferedImage> CACHE = new HashMap<>();

    /** @param name one of: login_photo, logo, box, cart, laptop (null if it cannot be decoded) */
    public static synchronized BufferedImage get(String name) {
        if (CACHE.containsKey(name)) return CACHE.get(name);
        BufferedImage img = null;
        try {
            String[] parts;
            switch (name) {
                case "login_photo": parts = LOGIN_PHOTO; break;
                case "logo":        parts = LOGO; break;
                case "box":         parts = BOX; break;
                case "cart":        parts = CART; break;
                case "laptop":      parts = LAPTOP; break;
                default:            parts = null;
            }
            if (parts != null) {
                img = ImageIO.read(new ByteArrayInputStream(Base64.getDecoder().decode(String.join("", parts))));
            }
        } catch (IOException | IllegalArgumentException ignored) { }
        CACHE.put(name, img);
        return img;
    }

    private static final String[] LOGIN_PHOTO = {
        "",
        "",
        "",
        ""
    };

    private static final String[] LOGO = {
        "",
        "",
        ""
    };

    private static final String[] BOX = {
        ""
    };

    private static final String[] CART = {
        ""
    };

    private static final String[] LAPTOP = {
        ""
    };

}
